    if (material && variant.inputMode !== "deferred") fs.writeFileSync(material, plan.materials[variant.material]);
    const updateMaterial = variant.supplementalMaterial ? path.join(consumer, uuid() + ".md") : null;
    cases[variant.id] = { base: variant.base, plannedTurns: variant.turns.length, consumer, material, inputMode: variant.inputMode ?? "file", materialSha256: variant.material ? digest(Buffer.from(plan.materials[variant.material])) : null, updateMaterial, updateMaterialSha256: updateMaterial ? digest(Buffer.from(plan.materials[variant.supplementalMaterial])) : null, scopeRefusalEligible: variant.scopeRefusalEligible === true, attempts: [], behaviorStatus: "UNKNOWN", executionStatus: "NOT_RUN" };
  }
  const batch = { schemaVersion: 1, runId, created: now(), reviewerRoot: REVIEWER, recordRoot, planFile, source: { repo, canonicalSha: canonical, canonicalTree: git(repo, ["rev-parse", `${canonical}^{tree}`]).trim() }, mirror: { root: paths.mirror, copied, excluded, identity: "exact file inventory; no equality claim with complete canonical tree" }, paths, vector, baselineVersion, configuredIdentity: profile, baselineCompatibility: { proofPath, proofSha256: digest(fs.readFileSync(proofPath)), originalDesktop: profile.values, actualDefault: actualDefaultValues, effectiveBaseline: effectiveValues, selectedIdentity: effectiveValues, reasoningSelection: { requested: requestedReasoningEffort ?? null, explicit: requestedReasoningEffort !== undefined, supportedByProof: requestedReasoningEffort === undefined ? null : true, supportedByFreshModelList: requestedReasoningEffort === undefined ? null : true, freshActualDefault: { model: preparedDefaultModels[0].model, model_reasoning_effort: preparedDefaultModels[0].defaultReasoningEffort }, freshModelsFile: path.join(recordRoot, "models.json"), freshModelsSha256: digest(fs.readFileSync(path.join(recordRoot, "models.json"))) }, reason: requestedReasoningEffort === undefined ? "actual pinned CLI model/list default after unsupported desktop model; separate fresh batch" : "explicit prepare reasoning effort; unchanged actual CLI model/default proof and fresh model/list support verified; selected identity is separate from actual default" }, isolation: { remotePluginDisabled: true, nativeInventory, nativeSkillsFile: path.join(recordRoot, "native-skills.json"), modelMetadataFile: path.join(recordRoot, "models.json"), originalHomeModified: false }, authentication: { copiedAuthFileOnly: true, sourceHome, secretsExcludedFromLogs: true }, packageVersion: manifest.version, cacheRoot, runtime, runtimeInventorySha256: digest(Buffer.from(runtime.map(r => `${r.relative}\t${r.cacheSha256}\n`).join(""))), selectedIds: selectedVariants.map(v => v.id), fullPlanFreshVariants: plan.freshVariants, fullPlanTurns: plan.plannedTurns, freshVariants: selectedVariants.length, plannedTurns, effectStatus: "NOT_MEASURED", cases };
  const batchFile = path.join(recordRoot, "batch.json"); saveBatch(batchFile, batch);
  writeJson(path.join(recordRoot, "preparation.json"), { schemaVersion: 1, runId, completed: now(), canonicalSha: canonical, paths, status: "VERIFIED_INSTALLATION_ONLY", modelStatus: "NOT_RUN", batchFile });
  return { batchFile, installationStatus: "VERIFIED_INSTALLATION_ONLY", modelStatus: "NOT_RUN", selectedIds: batch.selectedIds, freshVariants: batch.freshVariants, plannedTurns };
